@MainActor func transient_AutoLayoutPackageDocument_addDimensionButtonImage (
       _ prefs_packageDimensionColor : NSColor
) -> NSImage {
//--- START OF USER ZONE 2
        let temporaryObject = PackageDimension (nil)
        temporaryObject.x2 = .mil (100)
        temporaryObject.y2 = .mil (100)
        temporaryObject.drawDimensionBackground = false
        if let displayShape = temporaryObject.objectDisplay {
          let r = displayShape.boundingBox
          if !r.isEmpty {
            return buildPDFimage (frame: r.insetBy(dx: .pt (-2.0), dy: .pt (-2.0)), shape: displayShape)
          }else{
            return NSImage (named: NSImage.statusPartiallyAvailableName)!
          }
        }else{
          return NSImage (named: NSImage.statusPartiallyAvailableName)!
        }
//--- END OF USER ZONE 2
}

